package com.certmanage.smtp;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mail.javamail.JavaMailSenderImpl;
import org.springframework.mail.SimpleMailMessage;
import com.certmanage.common.SecretStore;
import java.util.*;
import java.nio.charset.StandardCharsets;
import static com.certmanage.common.Errors.require;
@Service
public class SmtpService {
 private final com.certmanage.common.ExecutionLog logs;private final JdbcTemplate db;private final SecretStore secrets;public SmtpService(JdbcTemplate d,SecretStore s,com.certmanage.common.ExecutionLog logs){db=d;secrets=s;this.logs=logs;}
 public Map<String,Object> config(){var rows=db.queryForList("select * from smtp_config where id=1");if(rows.isEmpty())return Map.of("host","","port",587,"tlsMode","STARTTLS","username","","sender","","credentialConfigured",false);var r=rows.getFirst();return Map.of("host",r.get("SMTP_HOST"),"port",r.get("SMTP_PORT"),"tlsMode",r.get("TLS_MODE"),"username",Objects.toString(r.get("SMTP_USERNAME"),""),"sender",r.get("SENDER_ADDRESS"),"credentialConfigured",r.get("CREDENTIAL_CIPHERTEXT")!=null);}
 public void save(Map<String,Object>b,long user){String host=Objects.toString(b.get("host"),"").trim(),sender=Objects.toString(b.get("sender"),"").trim(),mode=Objects.toString(b.get("tlsMode"),"STARTTLS");int port=((Number)b.getOrDefault("port",587)).intValue();require(!host.isBlank()&&host.length()<=255&&port>0&&port<65536,"SMTP地址或端口错误");require(validEmail(sender),"发件邮箱错误");require(Set.of("STARTTLS","TLS").contains(mode),"必须启用TLS加密");var old=db.queryForList("select * from smtp_config where id=1");byte[] cipher=null,nonce=null;String password=Objects.toString(b.get("password"),"");if(!old.isEmpty()){cipher=(byte[])old.getFirst().get("CREDENTIAL_CIPHERTEXT");nonce=(byte[])old.getFirst().get("CREDENTIAL_NONCE");}if(!password.isEmpty()){var s=secrets.seal(password.getBytes(StandardCharsets.UTF_8));cipher=s.ciphertext();nonce=s.nonce();}db.update("merge into smtp_config(id,smtp_host,smtp_port,tls_mode,smtp_username,credential_ciphertext,credential_nonce,encryption_key_id,sender_address,updated_by,updated_at) key(id) values(1,?,?,?,?,?,?,?,?,?,current_timestamp)",host,port,mode,Objects.toString(b.get("username"),""),cipher,nonce,cipher==null?null:"master-v1",sender,user);}
 public static boolean validEmail(String email){if(email==null||email.length()>320||email.contains("\r")||email.contains("\n"))return false;try{var a=new jakarta.mail.internet.InternetAddress(email,true);a.validate();return a.getAddress().contains("@");}catch(Exception e){return false;}}
 public void send(String recipient,String subject,String text){send(recipient,subject,text,null);}
 public void send(String recipient,String subject,String text,String messageId){logs.append("SMTP","SEND_STARTED","STARTED","smtp-worker",null,null,"SMTP",1L,"邮件发送开始",Map.of());try{sendMessage(recipient,subject,text,messageId);logs.appendAfterEffect("SMTP","SEND_SUCCESS","SUCCESS","smtp-worker",null,null,"SMTP",1L,"邮件发送成功",Map.of());}catch(RuntimeException e){logs.append("SMTP","SEND_FAILURE","FAILURE","smtp-worker",null,null,"SMTP",1L,"邮件发送失败，检查连接、TLS和凭据",Map.of());throw e;}}
 private void sendMessage(String recipient,String subject,String text,String messageId){require(validEmail(recipient),"收件邮箱错误");var rows=db.queryForList("select * from smtp_config where id=1");require(!rows.isEmpty(),"请先配置SMTP服务");var r=rows.getFirst();var sender=new JavaMailSenderImpl();sender.setHost((String)r.get("SMTP_HOST"));sender.setPort(((Number)r.get("SMTP_PORT")).intValue());sender.setUsername((String)r.get("SMTP_USERNAME"));if(r.get("CREDENTIAL_CIPHERTEXT")!=null)sender.setPassword(new String(secrets.open((byte[])r.get("CREDENTIAL_CIPHERTEXT"),(byte[])r.get("CREDENTIAL_NONCE")),StandardCharsets.UTF_8));var props=sender.getJavaMailProperties();props.setProperty("mail.smtp.auth",Boolean.toString(r.get("SMTP_USERNAME")!=null&&!r.get("SMTP_USERNAME").toString().isBlank()));props.setProperty("mail.smtp.connectiontimeout","10000");props.setProperty("mail.smtp.timeout","10000");props.setProperty("mail.smtp.writetimeout","10000");props.setProperty("mail.smtp.ssl.checkserveridentity","true");if("TLS".equals(r.get("TLS_MODE")))props.setProperty("mail.smtp.ssl.enable","true");else{props.setProperty("mail.smtp.starttls.enable","true");props.setProperty("mail.smtp.starttls.required","true");}try{var mail=new jakarta.mail.internet.MimeMessage(sender.getSession()){@Override protected void updateMessageID() throws jakarta.mail.MessagingException {if(messageId!=null)setHeader("Message-ID",messageId);else super.updateMessageID();}};var helper=new org.springframework.mail.javamail.MimeMessageHelper(mail,"UTF-8");helper.setFrom((String)r.get("SENDER_ADDRESS"));helper.setTo(recipient);helper.setSubject(subject);helper.setText(text);sender.send(mail);}catch(jakarta.mail.MessagingException e){throw new IllegalArgumentException("邮件构造失败");}}
}

